payload.template:
// A counter whose second output changes one bit at a time.

module gray_counter #(
    parameter int W = 4
) (
    input  logic         clk,
    input  logic         rst_n,    // synchronous, active low
    input  logic         en,       // advance on this edge
    output logic [W-1:0] bin,      // the ordinary count
    output logic [W-1:0] gray      // the same count in Gray code
);

    // your code here.
    //
    // Hold the ordinary count in a register and produce the Gray code
    // from it combinationally. Do not try to add one to a Gray code
    // directly: it is possible and it is far more logic than the
    // conversion.
    //
    // `bin` wraps from all-ones back to zero, and so does `gray`.

    assign bin  = '0;
    assign gray = '0;

endmodule

payload.testbench:
`timescale 1ns/1ps

// The sample testbench. Submit uses another one, which walks the whole
// range and checks that every single step moves one bit.
module tb;

  localparam int W = 4;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic rst_n = 1'b1;
  logic en    = 1'b0;
  logic [W-1:0] bin, gray;

  gray_counter #(.W(W)) dut (
    .clk(clk), .rst_n(rst_n), .en(en), .bin(bin), .gray(gray)
  );

  integer i;
  logic [W-1:0] prev;
  integer changed, worst;

  // One cycle: drive at the falling edge, return just after the rising
  // one, so what is read is what the edge produced.
  task tick(input logic e);
    begin
      @(negedge clk); en = e;
      @(posedge clk); #1;
    end
  endtask

  task reset;
    begin
      @(negedge clk); rst_n = 1'b0; en = 1'b0;
      @(posedge clk); #1;
      rst_n = 1'b1;
    end
  endtask

  // How many bits differ between two values.
  function automatic integer bits_differing(input [W-1:0] a, input [W-1:0] b);
    integer k, c;
    begin
      c = 0;
      for (k = 0; k < W; k = k + 1) if (a[k] !== b[k]) c = c + 1;
      bits_differing = c;
    end
  endfunction

  logic [W-1:0] b0, g0, b1, g1, b2, g2, b_held;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    reset();
    b0 = bin; g0 = gray;

    tick(1'b1);
    b1 = bin; g1 = gray;

    tick(1'b1);
    b2 = bin; g2 = gray;

    // Disabled: nothing moves.
    tick(1'b0);
    b_held = bin;

    $display("CHECK bin_zero_after_reset 0 %0d AT %0d", b0, $time);
    $display("CHECK gray_zero_after_reset 0 %0d AT %0d", g0, $time);
    $display("CHECK bin_counts 1 %0d AT %0d", b1, $time);
    $display("CHECK gray_of_one 1 %0d AT %0d", g1, $time);
    $display("CHECK gray_of_two 3 %0d AT %0d", g2, $time);
    $display("CHECK holds_when_disabled 2 %0d AT %0d", b_held, $time);
    $display("DONE 6");
    $finish;
  end

endmodule
